// Example invoice arithmetic. Amounts are integer minor units of the supplied currency.
const incoming = $input.all();
if (incoming.length !== 1) throw new Error('INVOICE_ONE_INPUT_REQUIRED');
const input = incoming[0].json;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const allowed = new Set(['invoiceId', 'currency', 'lines', 'discountMinor', 'taxBasisPoints']);
if (!object(input) || Object.keys(input).some(key => !allowed.has(key))) throw new Error('INVOICE_INPUT_INVALID');
if (typeof input.invoiceId !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$/.test(input.invoiceId)) throw new Error('INVOICE_ID_INVALID');
if (typeof input.currency !== 'string' || !/^[A-Z]{3}$/.test(input.currency)) throw new Error('INVOICE_CURRENCY_INVALID');
if (!Array.isArray(input.lines) || input.lines.length < 1 || input.lines.length > 200) throw new Error('INVOICE_LINES_INVALID');
const integer = (value, name, minimum = 0, maximum = Number.MAX_SAFE_INTEGER) => {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) throw new Error('INVOICE_' + name + '_INVALID');
  return value;
};
const publicInteger = (value, name) => {
  if (value < 0n || value > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error('INVOICE_' + name + '_OVERFLOW');
  return Number(value);
};
let subtotal = 0n, quantityTotal = 0n;
const lines = input.lines.map((line, index) => {
  if (!object(line) || Object.keys(line).some(key => !['description', 'quantity', 'unitPriceMinor'].includes(key))) throw new Error('INVOICE_LINE_INVALID_' + index);
  if (typeof line.description !== 'string' || !line.description.trim() || line.description.length > 200 || /[\x00-\x1f\x7f]/.test(line.description)) throw new Error('INVOICE_DESCRIPTION_INVALID_' + index);
  const quantity = integer(line.quantity, 'QUANTITY', 1, 10000);
  const unitPriceMinor = integer(line.unitPriceMinor, 'UNIT_PRICE');
  const lineTotal = BigInt(quantity) * BigInt(unitPriceMinor);
  subtotal += lineTotal; quantityTotal += BigInt(quantity);
  return { description: line.description, quantity, unitPriceMinor, lineTotalMinor: publicInteger(lineTotal, 'LINE_TOTAL') };
});
const discountMinor = integer(input.discountMinor ?? 0, 'DISCOUNT');
const taxBasisPoints = integer(input.taxBasisPoints ?? 0, 'TAX_RATE', 0, 10000);
const discount = BigInt(discountMinor);
if (discount > subtotal) throw new Error('INVOICE_DISCOUNT_EXCEEDS_SUBTOTAL');
const taxable = subtotal - discount;
// Round the single invoice-level tax to the nearest minor unit; halves round up.
const tax = (taxable * BigInt(taxBasisPoints) + 5000n) / 10000n;
const total = taxable + tax;
return [{ json: {
  invoiceId: input.invoiceId, currency: input.currency,
  lineCount: lines.length, totalQuantity: publicInteger(quantityTotal, 'QUANTITY_TOTAL'),
  subtotalMinor: publicInteger(subtotal, 'SUBTOTAL'), discountMinor,
  taxableMinor: publicInteger(taxable, 'TAXABLE'), taxBasisPoints,
  taxMinor: publicInteger(tax, 'TAX'), totalMinor: publicInteger(total, 'TOTAL'),
  rounding: 'invoice-tax-half-up', lines
} }];
